/**
 * Pure unit tests for OpportunityForecastService.weightedAmountByStage(Set<Id>).
 *
 * The IOpportunitiesSelector is mocked with ApexMocks and registered on the
 * Application.Selector factory, so these tests execute no SOQL and no DML.
 * Opportunities are built in memory with fake ids from fflib_IDGenerator.
 */
@IsTest
private class OpportunityForecastServiceTest {

    private static final String STAGE_PROSPECTING = 'Prospecting';
    private static final String STAGE_NEGOTIATION = 'Negotiation/Review';

    /**
     * Sums Amount * Probability / 100 per StageName across the opportunities
     * returned by the selector.
     */
    @IsTest
    static void weightedAmountByStage_sumsWeightedAmountPerStage() {
        // Arrange
        Set<Id> accountIds = new Set<Id>{
            fflib_IDGenerator.generate(Account.SObjectType),
            fflib_IDGenerator.generate(Account.SObjectType)
        };
        Id accountId = new List<Id>(accountIds)[0];

        List<Opportunity> opportunities = new List<Opportunity>{
            buildOpportunity(accountId, STAGE_PROSPECTING, 100.00, 50),
            buildOpportunity(accountId, STAGE_PROSPECTING, 200.00, 25),
            buildOpportunity(accountId, STAGE_NEGOTIATION, 300.00, 10)
        };

        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);

        mocks.startStubbing();
        mocks.when(selectorMock.selectOpenByAccountIds(accountIds)).thenReturn(opportunities);
        mocks.stopStubbing();

        // Act
        Test.startTest();
        Map<String, Decimal> totals = OpportunityForecastService.weightedAmountByStage(accountIds);
        Test.stopTest();

        // Assert
        System.assertEquals(2, totals.size(), 'Only the two populated stages should be returned');
        assertAmount(Decimal.valueOf('100.00'), totals.get(STAGE_PROSPECTING),
            'Prospecting should be 100 * 50% + 200 * 25% = 100.00');
        assertAmount(Decimal.valueOf('30.00'), totals.get(STAGE_NEGOTIATION),
            'Negotiation/Review should be 300 * 10% = 30.00');

        ((IOpportunitiesSelector) mocks.verify(selectorMock, 1)).selectOpenByAccountIds(accountIds);
    }

    /**
     * Each opportunity is rounded to two decimals before being summed, so
     * 10.01 * 33% = 3.3033 -> 3.30 each and the total is 6.60, not 6.61.
     */
    @IsTest
    static void weightedAmountByStage_roundsEachOpportunityBeforeSumming() {
        // Arrange
        Set<Id> accountIds = new Set<Id>{ fflib_IDGenerator.generate(Account.SObjectType) };
        Id accountId = new List<Id>(accountIds)[0];

        List<Opportunity> opportunities = new List<Opportunity>{
            buildOpportunity(accountId, STAGE_PROSPECTING, 10.01, 33),
            buildOpportunity(accountId, STAGE_PROSPECTING, 10.01, 33)
        };

        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);

        mocks.startStubbing();
        mocks.when(selectorMock.selectOpenByAccountIds(accountIds)).thenReturn(opportunities);
        mocks.stopStubbing();

        // Act
        Test.startTest();
        Map<String, Decimal> totals = OpportunityForecastService.weightedAmountByStage(accountIds);
        Test.stopTest();

        // Assert
        assertAmount(Decimal.valueOf('6.60'), totals.get(STAGE_PROSPECTING),
            'Each opportunity is rounded to 3.30 before summing, so the total is 6.60 and not 6.61');
    }

    /**
     * Opportunities missing Amount or Probability are ignored.
     */
    @IsTest
    static void weightedAmountByStage_ignoresOpportunitiesWithoutAmountOrProbability() {
        // Arrange
        Set<Id> accountIds = new Set<Id>{ fflib_IDGenerator.generate(Account.SObjectType) };
        Id accountId = new List<Id>(accountIds)[0];

        List<Opportunity> opportunities = new List<Opportunity>{
            buildOpportunity(accountId, STAGE_PROSPECTING, null, 50),
            buildOpportunity(accountId, STAGE_PROSPECTING, 100.00, null),
            buildOpportunity(accountId, STAGE_PROSPECTING, 100.00, 50)
        };

        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);

        mocks.startStubbing();
        mocks.when(selectorMock.selectOpenByAccountIds(accountIds)).thenReturn(opportunities);
        mocks.stopStubbing();

        // Act
        Test.startTest();
        Map<String, Decimal> totals = OpportunityForecastService.weightedAmountByStage(accountIds);
        Test.stopTest();

        // Assert
        System.assertEquals(1, totals.size(), 'Only the opportunity with both Amount and Probability counts');
        assertAmount(Decimal.valueOf('50.00'), totals.get(STAGE_PROSPECTING),
            'The complete opportunity should contribute 100 * 50% = 50.00');
    }

    /**
     * A null account id set returns an empty map without touching the selector.
     */
    @IsTest
    static void weightedAmountByStage_nullAccountIds_returnsEmptyMapWithoutSelecting() {
        // Arrange
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);

        // Act
        Test.startTest();
        Map<String, Decimal> totals = OpportunityForecastService.weightedAmountByStage(null);
        Test.stopTest();

        // Assert
        System.assertEquals(0, totals.size(), 'A null account id set should yield an empty map');
        ((IOpportunitiesSelector) mocks.verify(selectorMock, 0))
            .selectOpenByAccountIds((Set<Id>) fflib_Match.anyObject());
    }

    /**
     * An empty account id set returns an empty map without touching the selector.
     */
    @IsTest
    static void weightedAmountByStage_emptyAccountIds_returnsEmptyMapWithoutSelecting() {
        // Arrange
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);

        // Act
        Test.startTest();
        Map<String, Decimal> totals = OpportunityForecastService.weightedAmountByStage(new Set<Id>());
        Test.stopTest();

        // Assert
        System.assertEquals(0, totals.size(), 'An empty account id set should yield an empty map');
        ((IOpportunitiesSelector) mocks.verify(selectorMock, 0))
            .selectOpenByAccountIds((Set<Id>) fflib_Match.anyObject());
    }

    /**
     * Builds an in-memory Opportunity with a fake id. No DML is performed.
     */
    private static Opportunity buildOpportunity(Id accountId, String stageName, Decimal amount, Integer probability) {
        return new Opportunity(
            Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
            AccountId = accountId,
            StageName = stageName,
            Amount = amount,
            Probability = probability,
            CloseDate = Date.today().addDays(30)
        );
    }

    /**
     * Compares two decimals numerically, ignoring scale.
     */
    private static void assertAmount(Decimal expected, Decimal actual, String message) {
        System.assert(actual != null, message);
        System.assertEquals(0, expected.setScale(2).compareTo(actual.setScale(2)), message);
    }
}
