/**
 * ContactPhoneCleanup
 *
 * Normalizes Contact.Phone into the format the new dialer accepts: digits plus
 * an optional leading '+'. Every other character is removed.
 *
 * The class runs in user mode (sharing + object/field permissions) so a caller
 * cannot use it to read or edit Contacts/fields the running user has no access
 * to. If this is meant to run in system context (e.g. from a system-mode
 * integration), see the note in the answer about switching to SYSTEM_MODE.
 */
public with sharing class ContactPhoneCleanup {

    /** Anything that is not a digit or a plus sign gets stripped. */
    @TestVisible
    private static final String NON_DIALABLE_CHARS = '[^0-9+]';

    /**
     * Cleans the phone number of every Contact in `contactIds` and persists the
     * changes in a single, partial-success DML call.
     *
     * @param contactIds Contacts to normalize. Designed for up to 200 per call.
     * @return Map of Contact Id -> first error message for every Contact that
     *         could not be saved. Empty when every record saved.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failedById = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return failedById;
        }

        // One query, only the fields we touch. Contacts without a phone are
        // left out of the DML entirely.
        List<Contact> toUpdate = new List<Contact>();
        for (Contact contact : [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
            WITH USER_MODE
        ]) {
            if (String.isNotBlank(contact.Phone)) {
                contact.Phone = contact.Phone.replaceAll(NON_DIALABLE_CHARS, '');
                toUpdate.add(contact);
            }
        }

        if (toUpdate.isEmpty()) {
            return failedById;
        }

        // allOrNone = false so one bad record does not block the rest.
        List<Database.SaveResult> results =
            Database.update(toUpdate, false, AccessLevel.USER_MODE);

        // SaveResult order matches the input list order, so index-align them.
        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult result = results[i];
            if (!result.isSuccess()) {
                failedById.put(toUpdate[i].Id, result.getErrors()[0].getMessage());
            }
        }

        return failedById;
    }
}
