/**
 * Creates one follow-up Task per Opportunity coming out of the weekly pipeline review.
 *
 * Partial-success contract: a Task that is rejected (validation rule, required field,
 * duplicate rule, etc.) must not prevent the other Tasks from being created. The method
 * therefore returns the Ids of the Opportunities whose Task could NOT be created.
 *
 * Bulk-safe: the whole batch is written with a single all-or-none=false DML call rather
 * than one insert per record, so it stays well inside governor limits for the 150-250
 * Opportunity reviews it is designed for.
 */
public with sharing class FollowUpTaskService {

    /** Number of days from today that the follow-up is due. */
    @TestVisible
    private static final Integer FOLLOW_UP_DUE_IN_DAYS = 7;

    /** Prefix applied to the Opportunity name to build the Task subject. */
    @TestVisible
    private static final String SUBJECT_PREFIX = 'Follow up: ';

    /**
     * Creates a follow-up Task for every Opportunity in `opportunityIds`.
     *
     * @param opportunityIds Opportunity Ids to create follow-ups for. Null/blank entries
     *        are ignored; duplicates are only actioned once.
     * @return The Ids of the Opportunities for which no Task could be created. Empty when
     *         every Task was created successfully.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // De-duplicate so a repeated Id cannot produce a second Task.
        Set<Id> uniqueOpportunityIds = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                uniqueOpportunityIds.add(opportunityId);
            }
        }
        if (uniqueOpportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // One query for the whole batch; USER_MODE enforces object/field access and sharing.
        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>([
            SELECT Id, Name, OwnerId
            FROM Opportunity
            WHERE Id IN :uniqueOpportunityIds
            WITH USER_MODE
        ]);

        // Requested but not returned => deleted or not visible to the running user, so no
        // Task can exist for it. Report those as failures up front.
        for (Id opportunityId : uniqueOpportunityIds) {
            if (!opportunitiesById.containsKey(opportunityId)) {
                failedOpportunityIds.add(opportunityId);
            }
        }

        List<Task> tasksToInsert = new List<Task>();
        // Index-aligned with tasksToInsert so SaveResults can be mapped back to Opportunities.
        List<Id> taskOpportunityIds = new List<Id>();

        Date dueDate = Date.today().addDays(FOLLOW_UP_DUE_IN_DAYS);
        for (Opportunity opportunity : opportunitiesById.values()) {
            tasksToInsert.add(new Task(
                WhatId = opportunity.Id,
                OwnerId = opportunity.OwnerId,
                Subject = SUBJECT_PREFIX + opportunity.Name,
                ActivityDate = dueDate,
                Status = 'Not Started',
                Priority = 'Normal'
            ));
            taskOpportunityIds.add(opportunity.Id);
        }

        if (tasksToInsert.isEmpty()) {
            return failedOpportunityIds;
        }

        List<Database.SaveResult> results;
        try {
            // allOrNone = false => record-level failures are returned instead of throwing,
            // which is exactly the partial-success behaviour we need. One DML statement total.
            results = Database.insert(tasksToInsert, false, AccessLevel.USER_MODE);
        } catch (DmlException dmlException) {
            // Nothing at the record level should throw with allOrNone=false, but if the
            // statement itself fails, treat every Opportunity as failed rather than losing it.
            failedOpportunityIds.addAll(taskOpportunityIds);
            return failedOpportunityIds;
        }

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                failedOpportunityIds.add(taskOpportunityIds[i]);
            }
        }

        return failedOpportunityIds;
    }
}
