/**
 * Keeps Contact.MailingCountry aligned with Account.BillingCountry.
 *
 * When an Account's BillingCountry changes, every Contact on that Account
 * whose MailingCountry is blank, or still holds the Account's *previous*
 * BillingCountry, is moved to the new country. Contacts with any other
 * MailingCountry (people working abroad) and Contacts of Accounts whose
 * BillingCountry did not change are left untouched.
 *
 * Bulk-safe:
 *   - no SOQL or DML inside loops;
 *   - the single SOQL query is scoped to the Accounts in the current trigger
 *     batch instead of the entire Contact table;
 *   - all changes are written with one bulk DML.
 */
public with sharing class AccountCountrySync {

    /**
     * @param newAccounts Accounts from Trigger.new (after update).
     * @param oldAccounts Accounts from Trigger.oldMap, keyed by Id.
     */
    public static void syncMailingCountry(
        List<Account> newAccounts,
        Map<Id, Account> oldAccounts
    ) {
        if (newAccounts == null || newAccounts.isEmpty() || oldAccounts == null) {
            return;
        }

        // 1. Keep only the Accounts whose BillingCountry actually moved, and
        //    remember where each one moved from. Contacts are irrelevant for
        //    every other Account in the batch.
        Map<Id, Account> movedAccounts = new Map<Id, Account>();
        Map<Id, String> previousBillingCountry = new Map<Id, String>();

        for (Account newAccount : newAccounts) {
            Account oldAccount = oldAccounts.get(newAccount.Id);
            if (oldAccount != null
                && newAccount.BillingCountry != oldAccount.BillingCountry) {
                movedAccounts.put(newAccount.Id, newAccount);
                previousBillingCountry.put(newAccount.Id, oldAccount.BillingCountry);
            }
        }

        // Nothing moved in this batch: no query, no DML.
        if (movedAccounts.isEmpty()) {
            return;
        }

        // 2. One selective query, restricted to the Accounts in this batch.
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact contact : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :movedAccounts.keySet()
        ]) {
            Account movedAccount = movedAccounts.get(contact.AccountId);
            String oldCountry = previousBillingCountry.get(contact.AccountId);

            // Blank, or still on the Account's previous country.
            if (String.isBlank(contact.MailingCountry)
                || contact.MailingCountry == oldCountry) {
                contact.MailingCountry = movedAccount.BillingCountry;
                contactsToUpdate.add(contact);
            }
        }

        // 3. One bulk DML for everything that needs to change.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
