import { LightningElement, api } from 'lwc';
import LABEL_ADD from '@salesforce/label/c.Favorite_Add';
import LABEL_REMOVE from '@salesforce/label/c.Favorite_Remove';

export default class FavoriteToggle extends LightningElement {
    labels = {
        add: LABEL_ADD,
        remove: LABEL_REMOVE,
    };

    // Internal (private) state that backs the public `favorite` property.
    // Keeping the value here lets the button flip it optimistically without
    // reassigning the @api property, which the LWC lint rules forbid.
    _favorite = false;

    @api
    get favorite() {
        return this._favorite;
    }

    set favorite(value) {
        // The parent can set this at any time (e.g. after a server refresh);
        // normalizing to a boolean keeps the template logic simple.
        this._favorite = value === true;
    }

    get isFavorite() {
        return this._favorite;
    }

    // Label of the action a click performs: remove when favourite, add when not.
    get actionLabel() {
        return this.isFavorite ? this.labels.remove : this.labels.add;
    }

    get ariaPressed() {
        return this.isFavorite ? 'true' : 'false';
    }

    get iconClass() {
        return this.isFavorite
            ? 'favorite-toggle__icon favorite-toggle__icon_active'
            : 'favorite-toggle__icon';
    }

    handleClick() {
        // Optimistic UI: show the new value immediately, then notify the parent.
        const favorite = !this.isFavorite;
        this._favorite = favorite;

        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: { favorite },
                bubbles: true,
                composed: true,
            })
        );
    }
}
