```javascript
import { LightningElement, api } from 'lwc';

let instanceCount = 0;

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];

    // Unique per-instance prefix so option ids stay unique across the page.
    _listboxId = `statusListbox-${++instanceCount}`;

    // The selected value (controlled by the parent) and the currently
    // "active" option (referenced by aria-activedescendant, not focused).
    _value = '';
    _activeValue;

    @api
    get value() {
        return this._value;
    }

    set value(nextValue) {
        this._value = nextValue;
        // When the parent changes the value, the active option follows it.
        this._activeValue = nextValue;
    }

    get renderedOptions() {
        const activeIndex = this.activeIndex;
        return (this.options || []).map((option, index) => ({
            id: `${this._listboxId}-option-${index}`,
            value: option.value,
            label: option.label,
            ariaSelected: this._isSameValue(option.value, this._value)
                ? 'true'
                : 'false',
            className:
                index === activeIndex
                    ? 'slds-item slds-is-active'
                    : 'slds-item'
        }));
    }

    get activeDescendant() {
        const index = this.activeIndex;
        return index === -1 ? null : `${this._listboxId}-option-${index}`;
    }

    get activeIndex() {
        const options = this.options || [];
        if (options.length === 0) {
            return -1;
        }
        // Prefer the active option, then fall back to the selected option,
        // then to the first option.
        let index = options.findIndex((option) =>
            this._isSameValue(option.value, this._activeValue)
        );
        if (index === -1) {
            index = options.findIndex((option) =>
                this._isSameValue(option.value, this._value)
            );
        }
        return index === -1 ? 0 : index;
    }

    handleKeyDown(event) {
        const actions = {
            ArrowDown: () => this.moveActive(1),
            ArrowUp: () => this.moveActive(-1),
            Home: () => this.setActiveIndex(0),
            End: () => this.setActiveIndex((this.options || []).length - 1),
            Enter: () => this.selectActive(),
            ' ': () => this.selectActive()
        };
        const action = actions[event.key];
        if (action) {
            // Only these six keys are consumed; Tab and everything else keep
            // their default behaviour.
            event.preventDefault();
            action();
        }
    }

    handleOptionClick(event) {
        const rawValue = event.currentTarget.dataset.value;
        const option = (this.options || []).find((item) =>
            this._isSameValue(item.value, rawValue)
        );
        if (!option) {
            return;
        }
        this._activeValue = option.value;
        this.selectValue(option.value);
    }

    moveActive(offset) {
        const options = this.options || [];
        if (options.length === 0) {
            return;
        }
        const current = this.activeIndex;
        let next = current + offset;
        if (next < 0) {
            next = 0;
        } else if (next > options.length - 1) {
            next = options.length - 1;
        }
        this._activeValue = options[next].value;
    }

    setActiveIndex(index) {
        const options = this.options || [];
        if (index < 0 || index >= options.length) {
            return;
        }
        this._activeValue = options[index].value;
    }

    selectActive() {
        const options = this.options || [];
        const index = this.activeIndex;
        if (index < 0 || index >= options.length) {
            return;
        }
        this.selectValue(options[index].value);
    }

    selectValue(value) {
        if (this._isSameValue(value, this._value)) {
            // Already selected: nothing to dispatch.
            return;
        }
        this._value = value;
        this.dispatchEvent(new CustomEvent('change', { detail: { value } }));
    }

    _isSameValue(a, b) {
        if (a === b) {
            return true;
        }
        if (a === undefined || a === null || b === undefined || b === null) {
            return false;
        }
        return String(a) === String(b);
    }
}
