/**
 * FamilyService
 *
 * Records parent/child relationships in NPSP for a batch of student families.
 *
 * For every child -> parent pair, a single npe4__Relationship__c record is
 * inserted with the child as the Contact, the parent as the Related Contact and
 * the type "Parent" (status "Current"). NPSP's Relationship trigger then creates
 * the reciprocal record, resolving the child's reciprocal type (Son, Daughter or
 * Child) from the Relationship Lookup setting based on the child's gender. Each
 * pair therefore ends up with exactly one relationship record in each direction.
 *
 * The method is idempotent: any pair that already has a relationship in either
 * direction is skipped, so the import can safely be re-run.
 *
 * Bulk safety: at most one SOQL query and one DML statement are issued,
 * regardless of the number of pairs supplied.
 */
public with sharing class FamilyService {

    private static final String TYPE_PARENT = 'Parent';
    private static final String STATUS_CURRENT = 'Current';
    private static final String PAIR_SEPARATOR = '|';

    /**
     * Links each child Contact to its parent Contact in NPSP.
     *
     * @param parentIdByChildId Map of child Contact Id -> parent Contact Id.
     *                          Null or empty input is a no-op.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect the distinct Contact Ids, ignoring invalid entries (nulls and
        // self-referencing pairs).
        Set<Id> childIds = new Set<Id>();
        Set<Id> parentIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            childIds.add(childId);
            parentIds.add(parentId);
        }

        if (childIds.isEmpty()) {
            return;
        }

        // Single SOQL query: find any relationship that already joins one of the
        // supplied children to one of the supplied parents, in either direction.
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c relationship : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE (npe4__Contact__c IN :childIds AND npe4__RelatedContact__c IN :parentIds)
               OR (npe4__Contact__c IN :parentIds AND npe4__RelatedContact__c IN :childIds)
        ]) {
            if (relationship.npe4__Contact__c == null || relationship.npe4__RelatedContact__c == null) {
                continue;
            }
            // Register both orderings so a relationship in either direction is
            // recognised when checking a child -> parent pair below.
            existingPairs.add(pairKey(relationship.npe4__Contact__c, relationship.npe4__RelatedContact__c));
            existingPairs.add(pairKey(relationship.npe4__RelatedContact__c, relationship.npe4__Contact__c));
        }

        // Build the relationships that still need to be created.
        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            if (existingPairs.contains(pairKey(childId, parentId))) {
                continue;
            }
            relationshipsToInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = TYPE_PARENT,
                npe4__Status__c = STATUS_CURRENT
            ));
        }

        // Single DML statement. NPSP's trigger creates the reciprocal record for
        // each relationship, so both directions exist after this call.
        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }

    /**
     * Builds a directional key for an ordered Contact pair. Because both
     * orderings of an existing relationship are stored, a single lookup is
     * enough to detect a match regardless of direction.
     */
    private static String pairKey(Id contactId, Id relatedContactId) {
        return String.valueOf(contactId) + PAIR_SEPARATOR + String.valueOf(relatedContactId);
    }
}
