/**
 * Trigger Action: create an onboarding Task for the Account owner when a new
 * Account is created with Type "Customer - Direct" or "Customer - Channel".
 *
 * Registered on Account after insert through the Trigger_Action__mdt record
 * TA_Account_CreateOnboardingTask (Order 10). Accounts of any other Type (or
 * with no Type) are ignored, and no DML is performed unless at least one
 * qualifying Account was inserted in the current trigger execution.
 */
public with sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {
    private static final Set<String> ONBOARDING_ACCOUNT_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    public void afterInsert(List<SObject> triggerNew) {
        List<Task> onboardingTasks = new List<Task>();

        for (SObject record : triggerNew) {
            Account account = (Account) record;
            if (account.Type != null && ONBOARDING_ACCOUNT_TYPES.contains(account.Type)) {
                onboardingTasks.add(new Task(
                    Subject = 'Onboard new customer',
                    WhatId = account.Id,
                    OwnerId = account.OwnerId,
                    ActivityDate = Date.today().addDays(7),
                    Status = 'Not Started',
                    Priority = 'Normal'
                ));
            }
        }

        // Single DML statement for the whole batch; nothing runs when no
        // Account qualified.
        if (!onboardingTasks.isEmpty()) {
            insert onboardingTasks;
        }
    }
}
